{
  "schema_version": "2.0",
  "checklist_id": "FC-BEIM-001",
  "record_id": "HG-BEIM-001",
  "hypotheses": [
    {
      "hypothesis_id": "H1",
      "candidate_status": "candidate",
      "assumptions": [
        "The base edit produces its intended on-target molecular change in the edited immune cells of aged mice.",
        "The prespecified immune readouts measure the construct 'immune function' with adequate validity and are acquired and scored masked.",
        "On-target editing burden varies enough across animals to grade a dose-response relationship."
      ],
      "boundary_conditions": [
        "Aged mice of one strain, sex, vendor, and pathogen status; effects elsewhere are untested transport claims.",
        "One prespecified follow-up window; longer-horizon durability is a separate claim."
      ],
      "falsifier": {
        "prediction_id": "P1",
        "conditions": "Manipulation check (per-animal on-target editing fraction) and measurement checks pass, and uncertainty is small enough to distinguish the patterns.",
        "observable": "Prespecified immune readouts, on-target molecular change, and on-target editing fraction per animal at prespecified times.",
        "incompatible_result": "Recovery of readouts without the on-target molecular change, or recovery uncorrelated with on-target editing burden under adequate burden spread.",
        "assumption_failure_checks": [
          "Verify randomization, masking, editing-manipulation coverage, readout calibration, missingness, and temporal ordering before interpreting incompatibility."
        ]
      },
      "discriminating_tests": [
        {
          "test_id": "DT1",
          "rival_hypothesis_id": "H2",
          "focal_expected": "Sustained recovery tracking on-target burden with no assignment-linked shift in sham controls after the early window.",
          "rival_expected": "Early transient shifts present in sham controls and uncorrelated with editing burden.",
          "indeterminate_result": "Both patterns occur (mixed mechanisms): an innate-stimulation component on top of a genuine editing effect."
        },
        {
          "test_id": "DT2",
          "rival_hypothesis_id": "H3",
          "focal_expected": "Group effect survives masked, sham-controlled replication at the prespecified magnitude.",
          "rival_expected": "Effect shrinks toward zero under randomization, masking, and prespecified exclusions.",
          "indeterminate_result": "Shrunken but nonzero effect: cannot separate a real small effect from residual bias without a further replication."
        },
        {
          "test_id": "DT3",
          "rival_hypothesis_id": "H4",
          "focal_expected": "Recovery co-segregates with on-target burden; no assignment-linked excess off-target burden or damage markers.",
          "rival_expected": "Recovery co-segregates with off-target burden or DNA-damage markers instead of on-target editing.",
          "indeterminate_result": "Both on-target and off-target burden correlate with recovery: population remodeling and on-target reversal may coexist."
        },
        {
          "test_id": "DT4",
          "rival_hypothesis_id": "H5",
          "focal_expected": "Cell-intrinsic functional difference ex vivo, tracking burden and the on-target molecular change.",
          "rival_expected": "In vivo readouts improve without any cell-intrinsic ex vivo difference.",
          "indeterminate_result": "Weak ex vivo signal: cannot separate a systemic mechanism from failed ex vivo translation until PC1 assay performance is confirmed."
        }
      ],
      "nulls": [
        {
          "null_id": "N1",
          "statement": "Mean prespecified immune readouts are equal in edited and sham groups at the prespecified horizon.",
          "analysis_id": "A1",
          "interpretation_limit": "Failure to reject is not equivalence, absence of effect, or support for any rival."
        },
        {
          "null_id": "N2",
          "statement": "The slope of readout recovery on per-animal on-target editing burden is zero.",
          "analysis_id": "A2",
          "interpretation_limit": "A zero slope does not by itself prove a delivery/editor mechanism; burden spread and measurement error bound the claim."
        }
      ],
      "controls": [
        {
          "control_id": "NC1",
          "control_type": "negative_outcome",
          "rationale": "Sham base-editing control (same editor and delivery, non-targeting guide) cannot operate through the on-target mechanism but shares delivery, innate-stimulation, and handling bias pathways.",
          "expected_result": "No sustained prespecified-readout difference relative to baseline in the sham group beyond transient early shifts.",
          "failure_implication": "A sustained sham-group effect implicates delivery/editor or procedure; investigate before any causal interpretation of the edited group."
        },
        {
          "control_id": "NC2",
          "control_type": "negative_outcome",
          "rationale": "Untreated aged mice followed identically over the same window separate natural fluctuation, seasonality, and housing effects from procedure-linked ones.",
          "expected_result": "No prespecified-readout recovery over the window beyond multi-baseline drift.",
          "failure_implication": "Temporal drift in the colony or assay; recalibrate before interpreting treatment effects."
        },
        {
          "control_id": "PC1",
          "control_type": "positive_control",
          "rationale": "Young-adult comparator animals calibrate the assay ceiling and define the denominator of 'partial restoration'; the ex vivo assay is first validated on young vs aged cells.",
          "expected_result": "Young-adult readouts exceed aged baselines within the validated assay range.",
          "failure_implication": "Assay cannot detect the phenomenon class; the target test is not interpretable until measurement performance is restored."
        }
      ],
      "outcome_interpretation": {
        "consistent_with_candidate": "Sustained recovery tracking on-target burden, preceded by the on-target molecular change, absent in NC1/NC2, no off-target or damage-marker co-segregation, and a cell-intrinsic ex vivo difference - with controls passing and uncertainty within the prespecified interval.",
        "challenges_candidate": "Recovery without on-target molecular change or burden correlation; or sham-group recovery; or off-target/damage co-segregation - while manipulation, masking, and measurement remain credible.",
        "supports_neither_or_mixed": "Both mechanism and confound patterns occur, or an assumption or control fails; the candidates are then revised, not silently merged."
      },
      "human_review_status": "pending"
    },
    {
      "hypothesis_id": "H2",
      "candidate_status": "candidate",
      "assumptions": [
        "Vector- or editor-protein-driven innate stimulation measurably shifts the prespecified immune readouts in aged mice."
      ],
      "boundary_conditions": [
        "Same delivery route, dose, and formulation as the preliminary experiment."
      ],
      "falsifier": {
        "prediction_id": "P1",
        "conditions": "Sham controls measured with the same masked workflow and adequate early-window sampling.",
        "observable": "Early and late readout values in sham controls versus edited mice.",
        "incompatible_result": "Sham controls show no early transient shifts and readout changes occur only in proportion to on-target editing burden.",
        "assumption_failure_checks": [
          "Verify sham formulation matched the active arm and early windows were sampled before interpreting incompatibility."
        ]
      },
      "discriminating_tests": [
        {
          "test_id": "DT1",
          "rival_hypothesis_id": "H1",
          "focal_expected": "Early transient sham-group shifts uncorrelated with burden.",
          "rival_expected": "Sustained edited-group recovery tracking burden with no sham-group shift.",
          "indeterminate_result": "Both patterns occur: mixed mechanisms remain possible."
        }
      ],
      "nulls": [
        {
          "null_id": "N3",
          "statement": "Sham and edited groups have equal early-window readout means.",
          "analysis_id": "A1",
          "interpretation_limit": "Failure to reject does not establish the absence of innate stimulation when timing or sensitivity is insufficient."
        }
      ],
      "controls": [
        {
          "control_id": "NC1",
          "control_type": "negative_outcome",
          "rationale": "The sham control carries the entire delivery and editor-protein innate-stimulation pathway without any guide-directed edit.",
          "expected_result": "Under H2, sham shifts approximate edited-group early shifts.",
          "failure_implication": "No sham-group shift while edited mice recover challenges H2."
        }
      ],
      "outcome_interpretation": {
        "consistent_with_candidate": "Early transient shifts in sham controls matching the edited group, uncorrelated with burden.",
        "challenges_candidate": "Sham controls flat while edited-group recovery tracks burden over weeks.",
        "supports_neither_or_mixed": "Both patterns occur, or early-window sampling was inadequate."
      },
      "human_review_status": "pending"
    },
    {
      "hypothesis_id": "H3",
      "candidate_status": "candidate",
      "assumptions": [
        "The preliminary experiment's allocation, scoring, or sample continuity admitted selection, drift, or regression effects of the observed size."
      ],
      "boundary_conditions": [
        "Applies to the preliminary result as reported; the replication tests it directly."
      ],
      "falsifier": {
        "prediction_id": "P2",
        "conditions": "Replication runs randomized, masked, with prespecified exclusions and adequate n for the expected effect.",
        "observable": "Edited-versus-sham readout separation in the replication.",
        "incompatible_result": "The effect replicates at prespecified magnitude under masking and sham control.",
        "assumption_failure_checks": [
          "Verify randomization records, masking integrity, and exclusion-rule application before interpreting incompatibility."
        ]
      },
      "discriminating_tests": [
        {
          "test_id": "DT2",
          "rival_hypothesis_id": "H1",
          "focal_expected": "Effect vanishes or shrinks under rigorous replication.",
          "rival_expected": "Effect survives replication.",
          "indeterminate_result": "Shrunken nonzero effect cannot separate a small real effect from residual bias."
        }
      ],
      "nulls": [
        {
          "null_id": "N4",
          "statement": "Replication effect size is zero or below the prespecified minimum of interest.",
          "analysis_id": "A1",
          "interpretation_limit": "A null replication is consistent with H3 but also with an effect smaller than the study's power; power and interval, not the p-value, carry the interpretation."
        }
      ],
      "controls": [
        {
          "control_id": "NC2",
          "control_type": "negative_outcome",
          "rationale": "Untreated aged mice followed over the same window capture natural fluctuation and regression-to-the-mean dynamics.",
          "expected_result": "Under H3, the untreated and sham groups show drift comparable to the preliminary 'recovery'.",
          "failure_implication": "Stable untreated animals while sham-treated improve localize the bias to the procedure rather than time."
        }
      ],
      "outcome_interpretation": {
        "consistent_with_candidate": "Replication fails or shrinks under masking, randomization, and prespecified exclusions.",
        "challenges_candidate": "Effect survives rigorous replication at prespecified magnitude.",
        "supports_neither_or_mixed": "Replication is underpowered or deviates from the preliminary protocol in a way logged with expected impact."
      },
      "human_review_status": "pending"
    },
    {
      "hypothesis_id": "H4",
      "candidate_status": "candidate",
      "assumptions": [
        "Off-target edits or DNA-damage responses occur at levels sufficient to remodel immune-cell populations within the follow-up window."
      ],
      "boundary_conditions": [
        "Off-target panel covers predicted candidate sites only; genome-wide off-target mutations are not excluded by a negative panel."
      ],
      "falsifier": {
        "prediction_id": "P3",
        "conditions": "Panel and damage-marker assays validated, and on-target burden measured in the same animals.",
        "observable": "Off-target burden, damage markers, on-target burden, and recovery readouts per animal.",
        "incompatible_result": "Recovery co-segregates only with on-target burden while off-target burden and damage markers show no assignment-linked excess.",
        "assumption_failure_checks": [
          "Verify panel sensitivity at achieved editing levels and damage-marker timing before interpreting incompatibility."
        ]
      },
      "discriminating_tests": [
        {
          "test_id": "DT3",
          "rival_hypothesis_id": "H1",
          "focal_expected": "Recovery co-segregates with off-target burden or damage markers, not on-target editing.",
          "rival_expected": "Recovery co-segregates with on-target burden and molecular change.",
          "indeterminate_result": "Both correlate: mixed mechanisms remain possible."
        }
      ],
      "nulls": [
        {
          "null_id": "N5",
          "statement": "Off-target burden and damage-marker levels are equal in edited and sham groups.",
          "analysis_id": "A3",
          "interpretation_limit": "A null result bounds the evaluated sites and markers only; it does not certify genome-wide safety."
        }
      ],
      "controls": [
        {
          "control_id": "NC1",
          "control_type": "negative_outcome",
          "rationale": "Sham control carries editor exposure without guide-directed editing; under H4 its off-target and damage profile should differ from the edited arm.",
          "expected_result": "Edited arm shows higher off-target/damage signal than sham if H4 operates at measurable levels.",
          "failure_implication": "Equal profiles while only edited mice recover argue against a damage-mediated population shift."
        }
      ],
      "outcome_interpretation": {
        "consistent_with_candidate": "Recovery co-segregates with off-target burden or damage markers.",
        "challenges_candidate": "No assignment-linked off-target or damage excess while recovery tracks on-target editing.",
        "supports_neither_or_mixed": "Panel underpowered at achieved editing levels, or both mechanisms operate."
      },
      "human_review_status": "pending"
    }
  ]
}
